const HELIX_BIOLAB_HATCH_NORMAL_LOCAL=[0.5773502692,0.5773502692,0.5773502692];
const HELIX_BIOLAB_HATCH_U_LOCAL=[0.7071067812,-0.7071067812,0];
const HELIX_BIOLAB_HATCH_V_LOCAL=[0.4082482905,0.4082482905,-0.8164965809];
// The hatch size was approved at the original 13.5 lab scale. Keep the bay at
// that physical size even when the biolab hull is made much larger.
const HELIX_BIOLAB_HATCH_REFERENCE_SCALE=13.5;
const HELIX_BIOLAB_BOUND_RADIUS=HELIX_BIOLAB_MESH.v.reduce((r,p)=>Math.max(r,Math.hypot(p[0],p[1],p[2])),0);
// Build a real aperture in the selected buckyball face instead of painting a
// recess over a still-solid hull polygon. The station is intentionally scaled up
// to 34 in the story mission while the hatch keeps its original physical size, so
// the cut-out must be generated for the current lab scale rather than hard-coded.
function makeHelixBiolabHatchMesh(scale){
  const k=HELIX_BIOLAB_HATCH_REFERENCE_SCALE/Math.max(.001,scale||HELIX_BIOLAB_HATCH_REFERENCE_SCALE),halfW=.13*k,halfH=.086*k;
  const verts=HELIX_BIOLAB_MESH.v.map(p=>p.slice()),faces=HELIX_BIOLAB_MESH.faces.filter((_,i)=>i!==26).map(f=>f.slice());
  const inner=[[-halfW,-halfH],[halfW,-halfH],[halfW,halfH],[-halfW,halfH]].map(([du,dv])=>[
    HELIX_BIOLAB_HATCH_LOCAL[0]+HELIX_BIOLAB_HATCH_U_LOCAL[0]*du+HELIX_BIOLAB_HATCH_V_LOCAL[0]*dv,
    HELIX_BIOLAB_HATCH_LOCAL[1]+HELIX_BIOLAB_HATCH_U_LOCAL[1]*du+HELIX_BIOLAB_HATCH_V_LOCAL[1]*dv,
    HELIX_BIOLAB_HATCH_LOCAL[2]+HELIX_BIOLAB_HATCH_U_LOCAL[2]*du+HELIX_BIOLAB_HATCH_V_LOCAL[2]*dv
  ]);
  const ii=inner.map(v=>{verts.push(v);return verts.length-1}),o=HELIX_BIOLAB_HATCH_FACE;
  // Ten triangles exactly tile the hexagonal host panel around the rectangular
  // aperture. Nothing is drawn across the central hole, so hull occlusion remains
  // correct at oblique angles instead of the recess being painted through a wall.
  faces.push(
    [o[3],o[4],ii[3]],[o[3],ii[3],o[2]],[o[2],ii[3],ii[2]],[o[2],ii[2],o[1]],[o[1],ii[2],ii[1]],
    [o[1],ii[1],o[0]],[o[0],ii[1],o[5]],[o[5],ii[1],ii[0]],[o[5],ii[0],o[4]],[o[4],ii[0],ii[3]]
  );
  return{...HELIX_BIOLAB_MESH,name:'Helix Orbital Biolab — true hatch aperture',v:verts,faces}
}

const HELIX_PHEROMONE_CANISTER_MESH=(()=>{
  const v=[],faces=[],e=[],n=8;
  for(const z of[-1,1])for(let i=0;i<n;i++){const a=Math.PI/8+i*Math.PI*2/n;v.push([Math.cos(a)*.56,Math.sin(a)*.56,z])}
  faces.push([...Array(n).keys()].reverse(),[...Array(n).keys()].map(i=>i+n));
  for(let i=0;i<n;i++){const j=(i+1)%n;faces.push([i,j,j+n,i+n]);e.push([i,j],[i+n,j+n],[i,i+n])}
  return{name:'Helix pheromone canister',v,e,faces}
})();

